begin;
create table public.curriculum_source_documents (id uuid primary key default gen_random_uuid(), title text not null, source_url text not null unique, content_hash text not null, review_status text not null check (review_status in ('pending','verified','rejected')), retrieved_at timestamptz not null default now());
create table public.cycles (id uuid primary key default gen_random_uuid(), level_id uuid not null references public.levels(id), code text not null, official_text text, unique(level_id, code));
create table public.transversal_approaches (id uuid primary key default gen_random_uuid(), version_id uuid not null references public.curriculum_versions(id), code text not null, official_text text not null, unique(version_id, code));
alter table public.curriculum_versions add column if not exists source_document_id uuid references public.curriculum_source_documents(id);
alter table public.competencies add column if not exists source_document_id uuid references public.curriculum_source_documents(id), add column if not exists printed_page integer, add column if not exists pdf_page integer, add column if not exists section text, add column if not exists official_order integer, add column if not exists review_status text not null default 'pending' check (review_status in ('pending','verified','rejected')), add column if not exists reviewed_at timestamptz, add column if not exists content_hash text;
alter table public.performances add column if not exists source_document_id uuid references public.curriculum_source_documents(id), add column if not exists printed_page integer, add column if not exists pdf_page integer, add column if not exists section text, add column if not exists official_order integer, add column if not exists review_status text not null default 'pending' check (review_status in ('pending','verified','rejected')), add column if not exists reviewed_at timestamptz, add column if not exists content_hash text;
alter table public.capacities add column if not exists source_document_id uuid references public.curriculum_source_documents(id), add column if not exists printed_page integer, add column if not exists pdf_page integer, add column if not exists section text, add column if not exists official_order integer, add column if not exists review_status text not null default 'pending' check (review_status in ('pending','verified','rejected')), add column if not exists reviewed_at timestamptz, add column if not exists content_hash text;
alter table public.standards add column if not exists cycle_id uuid references public.cycles(id), add column if not exists source_document_id uuid references public.curriculum_source_documents(id), add column if not exists printed_page integer, add column if not exists pdf_page integer, add column if not exists section text, add column if not exists official_order integer, add column if not exists review_status text not null default 'pending' check (review_status in ('pending','verified','rejected')), add column if not exists reviewed_at timestamptz, add column if not exists content_hash text;
commit;
